package com.salvagehelper;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Value;

/** The messages the big on-screen banner shows right now, most urgent first. */
@Singleton
class Banner
{
	enum Level
	{
		DANGER,
		FULL,
		LIMIT,
		REMINDER
	}

	@Value
	static class Message
	{
		Level level;
		String text;
	}

	private final Map<String, Message> messages = new HashMap<>();

	void set(String key, Level level, String text)
	{
		messages.put(key, new Message(level, text));
	}

	void clear(String key)
	{
		messages.remove(key);
	}

	/** Sets the message while {@code show} is true and clears it otherwise. */
	void toggle(String key, boolean show, Level level, String text)
	{
		if (show)
		{
			set(key, level, text);
		}
		else
		{
			clear(key);
		}
	}

	List<Message> messages()
	{
		List<Message> list = new ArrayList<>(messages.values());
		list.sort(Comparator.comparing(Message::getLevel));
		return list;
	}

	void reset()
	{
		messages.clear();
	}
}

package com.salvagehelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** The big banner at the top of the game: danger, hold full, hold at your limit, and reminders. */
class BannerOverlay extends Overlay
{
	private static final int PAD_X = 14;
	private static final int PAD_Y = 6;
	private static final int GAP = 4;
	private static final long FLASH_MILLIS = 500;

	private final SalvageHelperConfig config;
	private final Banner banner;

	@Inject
	BannerOverlay(SalvageHelperConfig config, Banner banner)
	{
		this.config = config;
		this.banner = banner;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<Banner.Message> messages = banner.messages();
		if (!config.showBanner() || messages.isEmpty())
		{
			return null;
		}

		Font font = FontManager.getRunescapeBoldFont().deriveFont(config.bannerTextSize() * 1f);
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();

		int width = 0;
		for (Banner.Message message : messages)
		{
			width = Math.max(width, metrics.stringWidth(message.getText()) + PAD_X * 2);
		}
		int lineHeight = metrics.getHeight() + PAD_Y * 2;
		boolean dim = config.flashBanner() && (System.currentTimeMillis() / FLASH_MILLIS) % 2 == 0;

		int y = 0;
		for (Banner.Message message : messages)
		{
			Color background = background(message.getLevel());
			if (dim)
			{
				background = new Color(background.getRed(), background.getGreen(), background.getBlue(), 120);
			}
			graphics.setColor(background);
			graphics.fillRoundRect(0, y, width, lineHeight, 10, 10);

			int textX = (width - metrics.stringWidth(message.getText())) / 2;
			int textY = y + PAD_Y + metrics.getAscent();
			graphics.setColor(Color.BLACK);
			graphics.drawString(message.getText(), textX + 1, textY + 1);
			graphics.setColor(Color.WHITE);
			graphics.drawString(message.getText(), textX, textY);
			y += lineHeight + GAP;
		}
		return new Dimension(width, y - GAP);
	}

	private Color background(Banner.Level level)
	{
		switch (level)
		{
			case DANGER:
			case FULL:
				return config.fullBannerColor();
			case LIMIT:
				return config.limitBannerColor();
			default:
				return config.reminderBannerColor();
		}
	}
}

package com.salvagehelper;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Salvaging hooks, cargo holds and salvaging stations on boats, plus helpers for the player's own
 * boat.
 *
 * <p>Every boat is a WorldEntity with its own world view, and its objects use that world view's
 * local coordinates. The player's own boat is the world entity whose world view the player stands
 * in and whose owner type is {@link WorldEntity#OWNER_TYPE_SELF_PLAYER}, which also rules out
 * visiting someone else's boat. {@link WorldEntity#transformToMainWorld} turns a point on the boat
 * into a point on the sea, which is how hooks are compared with wrecks.
 */
@Singleton
class BoatObjects
{
	private final Client client;

	private final Set<GameObject> hooks = new HashSet<>();
	private final Set<GameObject> cargoHolds = new HashSet<>();
	private final Set<GameObject> stations = new HashSet<>();

	@Inject
	BoatObjects(Client client)
	{
		this.client = client;
	}

	void spawned(GameObject object)
	{
		int id = object.getId();
		if (SalvageIds.SALVAGING_HOOK_OBJECT_IDS.contains(id))
		{
			hooks.add(object);
		}
		else if (SalvageIds.CARGO_HOLD_OBJECT_IDS.contains(id))
		{
			cargoHolds.add(object);
		}
		else if (SalvageIds.SALVAGING_STATION_OBJECT_IDS.contains(id))
		{
			stations.add(object);
		}
	}

	void despawned(GameObject object)
	{
		hooks.remove(object);
		cargoHolds.remove(object);
		stations.remove(object);
	}

	void reset()
	{
		hooks.clear();
		cargoHolds.clear();
		stations.clear();
	}

	/** The boat the player stands on, if it is their own; null ashore or on another player's boat. */
	WorldEntity ownBoat()
	{
		Player player = client.getLocalPlayer();
		WorldView top = client.getTopLevelWorldView();
		if (player == null || top == null)
		{
			return null;
		}
		WorldView view = player.getWorldView();
		if (view == null || view.isTopLevel())
		{
			return null;
		}
		WorldEntity boat = top.worldEntities().byIndex(view.getId());
		return boat != null && boat.getOwnerType() == WorldEntity.OWNER_TYPE_SELF_PLAYER ? boat : null;
	}

	boolean isOnOwnBoat()
	{
		return ownBoat() != null;
	}

	/** The world view of the player's own boat, or null. */
	WorldView ownBoatView()
	{
		WorldEntity boat = ownBoat();
		return boat == null ? null : boat.getWorldView();
	}

	List<GameObject> ownHooks()
	{
		return onOwnBoat(hooks);
	}

	GameObject ownCargoHold()
	{
		List<GameObject> holds = onOwnBoat(cargoHolds);
		return holds.isEmpty() ? null : holds.get(0);
	}

	GameObject ownStation()
	{
		List<GameObject> found = onOwnBoat(stations);
		return found.isEmpty() ? null : found.get(0);
	}

	/** Slots in the own boat's hold, or -1 if the hold or its tier is unknown. */
	int ownHoldCapacity()
	{
		GameObject hold = ownCargoHold();
		if (hold == null)
		{
			return -1;
		}
		return SalvageIds.HOLD_CAPACITY.getOrDefault(hold.getId(), -1);
	}

	/** Where each of the own boat's hooks is on the sea right now. */
	List<WorldPoint> ownHookWorldPoints()
	{
		List<WorldPoint> points = new ArrayList<>();
		WorldEntity boat = ownBoat();
		if (boat == null)
		{
			return points;
		}
		for (GameObject hook : onOwnBoat(hooks))
		{
			WorldPoint point = toSea(boat, hook.getLocalLocation());
			if (point != null)
			{
				points.add(point);
			}
		}
		return points;
	}

	/** Where the own boat is on the sea, or null. */
	WorldPoint ownBoatWorldPoint()
	{
		WorldEntity boat = ownBoat();
		if (boat == null || boat.getLocalLocation() == null)
		{
			return null;
		}
		return WorldPoint.fromLocal(client, boat.getLocalLocation());
	}

	private WorldPoint toSea(WorldEntity boat, LocalPoint onBoat)
	{
		if (onBoat == null)
		{
			return null;
		}
		LocalPoint sea = boat.transformToMainWorld(onBoat);
		return sea == null ? null : WorldPoint.fromLocal(client, sea);
	}

	private List<GameObject> onOwnBoat(Set<GameObject> objects)
	{
		List<GameObject> result = new ArrayList<>();
		WorldView view = ownBoatView();
		if (view == null)
		{
			return result;
		}
		for (GameObject object : objects)
		{
			if (object.getWorldView() == view)
			{
				result.add(object);
			}
		}
		return result;
	}
}

package com.salvagehelper;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

/**
 * Promotes the cargo hold's deposit option to the left-click while the inventory holds something
 * the hold accepts (or, in "Only my list" mode, something on the player's own list).
 *
 * <p>This only reorders the client's own menu entries after it has sorted them (the same thing
 * RuneLite's Menu Entry Swapper does). It never creates, consumes or sends clicks: the player still
 * clicks, the game just receives the entry they would otherwise pick from the right-click menu.
 *
 * <p>The hold's deposit option is not always named the same ("Deposit", "Deposit-all",
 * "Quick-deposit" and "Deposit-held" have all been seen), so the configured names are tried first
 * and then any other deposit option except "Deposit-held", which only moves held task cargo.
 */
@Slf4j
@Singleton
class CargoHoldSwapper
{
	private static final String HELD_CARGO_OPTION = "deposit-held";

	private final Client client;
	private final SalvageHelperConfig config;
	private final ItemManager itemManager;

	/** Lower-cased option names to promote, in priority order. */
	private List<String> depositOptions = new ArrayList<>();
	/** Items that trigger the swap by id: the built-in set plus extras, or the IDs in "My list". */
	private Set<Integer> depositableIds = new HashSet<>();
	/** Lower-cased names (with * wildcards) from "My list"; only used in that mode. */
	private List<String> whitelistNames = new ArrayList<>();
	private boolean hasDepositable;
	/** The last set of hold options written to the log, so each distinct menu is logged once. */
	private String loggedOptions;

	@Inject
	CargoHoldSwapper(Client client, SalvageHelperConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;
	}

	/** Re-reads the option names, trigger and extra item IDs from config, then rechecks the inventory. */
	void reloadConfig()
	{
		List<String> options = new ArrayList<>();
		for (String option : Text.fromCSV(config.depositOptions()))
		{
			options.add(option.toLowerCase(Locale.ROOT));
		}
		depositOptions = options;

		Set<Integer> ids = new HashSet<>();
		List<String> names = new ArrayList<>();
		switch (config.depositTrigger())
		{
			case WHITELIST:
				// "My list" alone decides: each entry is an item ID or a name, * matching anything
				for (String entry : Text.fromCSV(config.depositWhitelist()))
				{
					Integer id = parseId(entry);
					if (id != null)
					{
						ids.add(id);
					}
					else if (!entry.isEmpty())
					{
						names.add(entry.toLowerCase(Locale.ROOT));
					}
				}
				break;
			case SALVAGE_ONLY:
				ids.addAll(SalvageIds.SALVAGE_ITEM_IDS);
				addExtraIds(ids);
				break;
			default:
				ids.addAll(SalvageIds.HOLD_ACCEPTED_ITEM_IDS);
				addExtraIds(ids);
				break;
		}
		depositableIds = ids;
		whitelistNames = names;

		updateInventory(client.getItemContainer(InventoryID.INV));
	}

	/**
	 * Caches whether the inventory holds a depositable item, so the per-frame menu hook does not have
	 * to scan the inventory. Called on every inventory change.
	 */
	void updateInventory(ItemContainer inventory)
	{
		hasDepositable = false;
		if (inventory == null)
		{
			return;
		}

		for (Item item : inventory.getItems())
		{
			if (item.getId() > 0 && isDepositable(item.getId()))
			{
				hasDepositable = true;
				return;
			}
		}
	}

	private boolean isDepositable(int itemId)
	{
		if (depositableIds.contains(itemId))
		{
			return true;
		}
		if (whitelistNames.isEmpty())
		{
			return false;
		}
		String name = itemManager.getItemComposition(itemId).getName();
		if (name == null)
		{
			return false;
		}
		name = name.toLowerCase(Locale.ROOT);
		for (String pattern : whitelistNames)
		{
			if (WildcardMatcher.matches(pattern, name))
			{
				return true;
			}
		}
		return false;
	}

	private void addExtraIds(Set<Integer> ids)
	{
		for (String entry : Text.fromCSV(config.extraDepositableIds()))
		{
			Integer id = parseId(entry);
			// Typos in the config box are skipped rather than breaking the whole list
			if (id != null)
			{
				ids.add(id);
			}
		}
	}

	private static Integer parseId(String text)
	{
		try
		{
			return Integer.parseInt(text.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	void reset()
	{
		hasDepositable = false;
		loggedOptions = null;
	}

	/** Called from PostMenuSort, i.e. once the client has finished ordering this frame's menu. */
	void swap()
	{
		// An open menu is not rebuilt each frame, so swapping it here would keep flipping entries
		if (!client.isMenuOpen())
		{
			reorder();
		}
	}

	/**
	 * Called when the right-click menu opens. Other plugins that rewrite the menu as it opens would
	 * otherwise put the original order back, so the swap is applied once more on the opened menu.
	 */
	void menuOpened()
	{
		reorder();
	}

	private void reorder()
	{
		if (!config.leftClickDepositAll() || !hasDepositable)
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		if (entries.length < 2)
		{
			return;
		}

		// The last entry is the left-click. Only touch the menu when the cursor's top target is the
		// cargo hold itself, so something drawn in front of it (a crewmate, the player) keeps its
		// normal left-click.
		MenuEntry top = entries[entries.length - 1];
		if (!isCargoHold(top))
		{
			return;
		}

		int depositIdx = findDepositEntry(entries, top);
		logOptionsOnce(entries, top, depositIdx);
		if (depositIdx < 0 || depositIdx == entries.length - 1)
		{
			return;
		}

		MenuEntry deposit = entries[depositIdx];
		System.arraycopy(entries, depositIdx + 1, entries, depositIdx, entries.length - 1 - depositIdx);
		entries[entries.length - 1] = deposit;
		menu.setMenuEntries(entries);
	}

	/**
	 * Matches by object ID first (from {@link SalvageIds#CARGO_HOLD_OBJECT_IDS}); falls back to a
	 * target name containing "cargo hold" in case a hold variant's ID is not listed.
	 */
	private static boolean isCargoHold(MenuEntry entry)
	{
		if (!isGameObjectOption(entry.getType()))
		{
			return false;
		}
		return SalvageIds.CARGO_HOLD_OBJECT_IDS.contains(entry.getIdentifier())
			|| Text.removeTags(entry.getTarget()).toLowerCase(Locale.ROOT).contains("cargo hold");
	}

	/**
	 * Finds the deposit option on the same object the top entry belongs to (same ID, same scene tile
	 * and same world view, so a second hold on screen is never picked): the configured names in order,
	 * then any other deposit option except "Deposit-held".
	 */
	private int findDepositEntry(MenuEntry[] entries, MenuEntry top)
	{
		for (String wanted : depositOptions)
		{
			for (int i = entries.length - 1; i >= 0; i--)
			{
				if (sameObject(entries[i], top) && wanted.equals(option(entries[i])))
				{
					return i;
				}
			}
		}
		for (int i = entries.length - 1; i >= 0; i--)
		{
			String option = option(entries[i]);
			if (sameObject(entries[i], top) && option.contains("deposit") && !option.equals(HELD_CARGO_OPTION))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Writes the hold's options to the debug log the first time each distinct menu is seen, so the
	 * real option names can be read from the debug log (client started with --debug).
	 */
	private void logOptionsOnce(MenuEntry[] entries, MenuEntry top, int depositIdx)
	{
		// Sorted, so the same menu before and after the swap logs only once
		TreeSet<String> options = new TreeSet<>();
		for (MenuEntry entry : entries)
		{
			if (sameObject(entry, top))
			{
				options.add(Text.removeTags(entry.getOption()));
			}
		}
		String summary = String.join(", ", options) + " (object " + top.getIdentifier() + ")";
		if (!summary.equals(loggedOptions))
		{
			loggedOptions = summary;
			log.debug("Cargo hold menu: {} -> {}", summary,
				depositIdx < 0 ? "no deposit option found" : "promoting \"" + Text.removeTags(entries[depositIdx].getOption()) + "\"");
		}
	}

	private static boolean sameObject(MenuEntry e, MenuEntry top)
	{
		return isGameObjectOption(e.getType())
			&& e.getIdentifier() == top.getIdentifier()
			&& e.getParam0() == top.getParam0()
			&& e.getParam1() == top.getParam1()
			&& e.getWorldViewId() == top.getWorldViewId();
	}

	private static String option(MenuEntry entry)
	{
		return Text.removeTags(entry.getOption()).toLowerCase(Locale.ROOT);
	}

	private static boolean isGameObjectOption(MenuAction type)
	{
		switch (type)
		{
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}
}

package com.salvagehelper;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;

/**
 * Keeps count of how many slots each boat's cargo hold is using.
 *
 * <h3>Exact counts and estimates</h3>
 * The game only sends a hold's contents (inventories 963-967, one per boat slot) while its
 * interface is open. That read is exact: every occupied slot counts once, since the hold's capacity
 * is measured in slots. Between reads the count is kept up by what can be seen:
 * <ul>
 *   <li>a crewmate's overhead line about hooking salvage or putting it in the hold: +1 slot;</li>
 *   <li>a crewmate saying the hold is full: the count jumps to the capacity;</li>
 *   <li>the "You deposit some cargo into the cargo hold" message: + the inventory slots that just
 *   emptied.</li>
 * </ul>
 * Anything else (a bank boat, a crewmate banking the hold at a dock) is missed until the hold is
 * opened again, which resyncs it. The count is marked as an estimate until then.
 *
 * <p>Each boat's count is saved to the RuneLite profile of the logged-in account, so it carries over
 * plugin reloads and client restarts as an estimate instead of starting from unknown.
 */
@Singleton
class CargoHoldTracker
{
	/** Fills older than this are ignored when working out the rate. */
	private static final long RATE_WINDOW_MILLIS = 10 * 60_000L;
	private static final long MIN_RATE_SPAN_MILLIS = 60_000L;
	private static final int MIN_RATE_EVENTS = 3;

	@Value
	static class Contents
	{
		int used;
		/** Slots in the hold, or -1 if unknown. */
		int capacity;
		int salvage;
		boolean estimate;

		boolean isFull()
		{
			return capacity > 0 && used >= capacity;
		}
	}

	private static final class Hold
	{
		int used;
		int salvage;
		boolean estimate;
	}

	private static final String SAVED_KEY = "holdCount_";

	private final Client client;
	private final BoatObjects boatObjects;
	private final ConfigManager configManager;

	private final Map<Integer, Hold> holds = new HashMap<>();
	/** (time, slots) pairs for recent fills, oldest first. */
	private final Deque<long[]> fills = new ArrayDeque<>();

	@Inject
	CargoHoldTracker(Client client, BoatObjects boatObjects, ConfigManager configManager)
	{
		this.client = client;
		this.boatObjects = boatObjects;
		this.configManager = configManager;
	}

	/** Exact read from the hold's inventory. @return true if the container was a cargo hold. */
	boolean containerChanged(int containerId, ItemContainer container)
	{
		int slot = slotFor(containerId);
		if (slot == 0)
		{
			return false;
		}

		Hold hold = holds.computeIfAbsent(slot, s -> new Hold());
		hold.used = 0;
		hold.salvage = 0;
		hold.estimate = false;
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > -1 && item.getQuantity() > 0)
				{
					hold.used++;
					if (SalvageIds.SALVAGE_ITEM_IDS.contains(item.getId()))
					{
						hold.salvage++;
					}
				}
			}
		}
		save(slot, hold);
		return true;
	}

	/** A crewmate said they put a piece of salvage in the hold. */
	void crewSalvaged()
	{
		add(1, 1);
	}

	/** The player deposited while the hold was closed; these inventory slots just emptied. */
	void playerDeposited(int slots, int salvage)
	{
		if (slots > 0)
		{
			add(slots, Math.max(0, salvage));
		}
	}

	/** A crewmate said the hold is full. */
	void holdReportedFull()
	{
		Hold hold = currentHold();
		int capacity = boatObjects.ownHoldCapacity();
		if (hold != null && capacity > 0)
		{
			hold.used = capacity;
			hold.estimate = true;
			save(currentSlot(), hold);
		}
	}

	/** The hold on the boat the player last boarded, or null if it has not been read yet. */
	Contents current()
	{
		Hold hold = currentHold();
		if (hold == null)
		{
			return null;
		}
		return new Contents(hold.used, boatObjects.ownHoldCapacity(), hold.salvage, hold.estimate);
	}

	/**
	 * Milliseconds until the hold is full at the recent fill rate, or -1 when there is not enough
	 * data (a few fills over at least a minute in the last ten).
	 */
	long millisToFull()
	{
		Contents contents = current();
		if (contents == null || contents.getCapacity() <= 0)
		{
			return -1;
		}
		if (contents.isFull())
		{
			return 0;
		}

		long now = System.currentTimeMillis();
		prune(now);
		if (fills.size() < MIN_RATE_EVENTS)
		{
			return -1;
		}
		long span = now - fills.peekFirst()[0];
		if (span < MIN_RATE_SPAN_MILLIS)
		{
			return -1;
		}
		long slots = 0;
		for (long[] fill : fills)
		{
			slots += fill[1];
		}
		double slotsPerMilli = (double) slots / span;
		return (long) ((contents.getCapacity() - contents.getUsed()) / slotsPerMilli);
	}

	void reset()
	{
		holds.clear();
		fills.clear();
	}

	private void add(int slots, int salvage)
	{
		Hold hold = currentHold();
		if (hold == null)
		{
			// Nothing to add to until the hold has been read once
			return;
		}
		int capacity = boatObjects.ownHoldCapacity();
		hold.used = capacity > 0 ? Math.min(capacity, hold.used + slots) : hold.used + slots;
		hold.salvage += salvage;
		hold.estimate = true;
		save(currentSlot(), hold);

		long now = System.currentTimeMillis();
		fills.addLast(new long[]{now, slots});
		prune(now);
	}

	private void prune(long now)
	{
		while (!fills.isEmpty() && now - fills.peekFirst()[0] > RATE_WINDOW_MILLIS)
		{
			fills.removeFirst();
		}
	}

	private int currentSlot()
	{
		int slot = client.getVarbitValue(SalvageIds.BOAT_SLOT_VARBIT);
		return slot >= 1 && slot <= SalvageIds.CARGO_HOLD_INVENTORIES.length ? slot : 0;
	}

	/** The current boat's hold: from this session, else the saved count as an estimate, else null. */
	private Hold currentHold()
	{
		int slot = currentSlot();
		if (slot == 0)
		{
			return null;
		}
		Hold hold = holds.get(slot);
		if (hold == null)
		{
			hold = load(slot);
			if (hold != null)
			{
				holds.put(slot, hold);
			}
		}
		return hold;
	}

	private void save(int slot, Hold hold)
	{
		if (slot != 0)
		{
			configManager.setRSProfileConfiguration(SalvageHelperConfig.GROUP, SAVED_KEY + slot,
				hold.used + "," + hold.salvage);
		}
	}

	private Hold load(int slot)
	{
		String saved = configManager.getRSProfileConfiguration(SalvageHelperConfig.GROUP, SAVED_KEY + slot);
		if (saved == null)
		{
			return null;
		}
		String[] parts = saved.split(",");
		try
		{
			Hold hold = new Hold();
			hold.used = Integer.parseInt(parts[0].trim());
			hold.salvage = parts.length > 1 ? Integer.parseInt(parts[1].trim()) : 0;
			// Anything could have happened since it was saved; opening the hold makes it exact again
			hold.estimate = true;
			return hold;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Boat slot 1-5 for a cargo hold inventory id, else 0. */
	private static int slotFor(int containerId)
	{
		int id = containerId & SalvageIds.CONTAINER_ID_MASK;
		if (id < InventoryID.SAILING_BOAT_1_CARGOHOLD || id > InventoryID.SAILING_BOAT_5_CARGOHOLD)
		{
			return 0;
		}
		return id - InventoryID.SAILING_BOAT_1_CARGOHOLD + 1;
	}
}

package com.salvagehelper;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.api.MenuAction;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * Shows how many cargo hold slots are used while on your boat; turns orange at your alert limit and
 * red when full. Right-click it and pick "Set alert limit" to type a new limit in the chatbox.
 */
class CargoInfoBox extends InfoBox
{
	static final String SET_LIMIT_OPTION = "Set alert limit";
	private static final String TARGET = "Cargo hold";
	private static final Color LIMIT_COLOR = new Color(255, 160, 0);

	private final SalvageHelperConfig config;
	private final CargoHoldTracker cargoHoldTracker;

	CargoInfoBox(BufferedImage image, Plugin plugin, SalvageHelperConfig config, CargoHoldTracker cargoHoldTracker)
	{
		super(image, plugin);
		this.config = config;
		this.cargoHoldTracker = cargoHoldTracker;
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_INFOBOX, SET_LIMIT_OPTION, TARGET));
	}

	@Override
	public String getText()
	{
		CargoHoldTracker.Contents contents = cargoHoldTracker.current();
		if (contents == null)
		{
			return "?";
		}
		return (contents.isEstimate() ? "~" : "") + contents.getUsed();
	}

	@Override
	public Color getTextColor()
	{
		CargoHoldTracker.Contents contents = cargoHoldTracker.current();
		if (contents == null)
		{
			return Color.WHITE;
		}
		if (contents.isFull())
		{
			return Color.RED;
		}
		return contents.getUsed() >= config.cargoLimit() ? LIMIT_COLOR : Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		CargoHoldTracker.Contents contents = cargoHoldTracker.current();
		String limit = "</br>Alert at " + config.cargoLimit() + " slots</br>Right-click to change the limit";
		if (contents == null)
		{
			return "Cargo hold: unknown until you open it" + limit;
		}
		String capacity = contents.getCapacity() > 0 ? "/" + contents.getCapacity() : "";
		String estimate = contents.isEstimate() ? "</br>Estimated since the hold was last opened" : "";
		return "Cargo hold: " + contents.getUsed() + capacity + " slots" + estimate + limit;
	}
}

package com.salvagehelper;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.gameval.DBTableID;
import net.runelite.client.util.Text;

/**
 * The player's crew and the job each is assigned to, straight from the game.
 *
 * <p>Varbits {@link SalvageIds#CREW_SLOT_VARBITS} hold which crewmate sits in each crew slot (their
 * unique id, 0 for an empty slot) and {@link SalvageIds#CREW_POSITION_VARBITS} the job they are on.
 * The game's crew table ({@link DBTableID.SailingCrew}) turns a unique id into the crewmate's NPCs
 * on deck: the boat NPC and the one carrying cargo. An NPC on the boat is matched to its slot by
 * NPC id (as spawned or transformed) and, if that fails, by name.
 */
@Slf4j
@Singleton
class CrewRoster
{
	static final class Member
	{
		final int uniqueId;
		final int position;
		final List<Integer> npcIds;
		final String name;

		Member(int uniqueId, int position, List<Integer> npcIds, String name)
		{
			this.uniqueId = uniqueId;
			this.position = position;
			this.npcIds = npcIds;
			this.name = name;
		}

		boolean onHook()
		{
			return SalvageIds.CREW_POSITION_HOOKS.contains(position);
		}
	}

	private static final class Lookup
	{
		final List<Integer> npcIds;
		final String name;

		Lookup(List<Integer> npcIds, String name)
		{
			this.npcIds = npcIds;
			this.name = name;
		}
	}

	private final Client client;
	/** Crew table lookups never change, so each unique id is read once. */
	private final Map<Integer, Lookup> lookups = new HashMap<>();

	@Inject
	CrewRoster(Client client)
	{
		this.client = client;
	}

	/** The current crew, one entry per filled slot. Client thread only. */
	List<Member> members()
	{
		List<Member> members = new ArrayList<>();
		for (int i = 0; i < SalvageIds.CREW_SLOT_VARBITS.length; i++)
		{
			int uniqueId = client.getVarbitValue(SalvageIds.CREW_SLOT_VARBITS[i]);
			if (uniqueId == 0)
			{
				continue;
			}
			int position = client.getVarbitValue(SalvageIds.CREW_POSITION_VARBITS[i]);
			Lookup lookup = lookups.computeIfAbsent(uniqueId, this::lookup);
			members.add(new Member(uniqueId, position, lookup.npcIds, lookup.name));
		}
		return members;
	}

	/** The crew slot this NPC belongs to, or null if it cannot be matched. */
	static Member find(List<Member> members, NPC npc)
	{
		int id = npc.getId();
		NPCComposition transformed = npc.getTransformedComposition();
		int transformedId = transformed == null ? -1 : transformed.getId();
		for (Member member : members)
		{
			if (member.npcIds.contains(id) || member.npcIds.contains(transformedId))
			{
				return member;
			}
		}

		String name = realName(npc.getName());
		if (name != null)
		{
			for (Member member : members)
			{
				if (name.equals(member.name))
				{
					return member;
				}
			}
		}
		return null;
	}

	void reset()
	{
		lookups.clear();
	}

	private Lookup lookup(int uniqueId)
	{
		List<Integer> npcIds = new ArrayList<>();
		String name = "";
		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SailingCrew.ID, DBTableID.SailingCrew.COL_UNIQUE_ID, 0, uniqueId);
			if (rows != null && !rows.isEmpty())
			{
				int row = rows.get(0);
				for (int column : new int[]{DBTableID.SailingCrew.COL_BOAT_NPC, DBTableID.SailingCrew.COL_CARGO_NPC})
				{
					Object[] field = client.getDBTableField(row, column, 0);
					if (field != null && field.length > 0 && field[0] instanceof Integer)
					{
						addVariants(npcIds, (Integer) field[0]);
					}
				}
				for (int npcId : npcIds)
				{
					NPCComposition definition = client.getNpcDefinition(npcId);
					String found = definition == null ? null : realName(definition.getName());
					if (found != null)
					{
						name = found;
						break;
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read crewmate {} from the crew table", uniqueId, e);
		}
		log.debug("Crew table: crewmate {} -> NPC ids {}, name \"{}\"", uniqueId, npcIds, name);
		return new Lookup(npcIds, name);
	}

	/**
	 * The crew table names the crewmate's base NPC (e.g. SAILING_CREW_GENERIC_4_SHIP, 15284), but on
	 * deck they show as one of its variants (_SHIP_OP 15285 or _SHIP_NO_OP 15286; for the cargo NPC
	 * _CARGO_2 / _CARGO_3), seen in game 2026-11-02. Every NPC the base can transform into is added,
	 * plus the next two ids in case the base lists no transforms.
	 */
	private void addVariants(List<Integer> npcIds, int baseId)
	{
		npcIds.add(baseId);
		NPCComposition base = client.getNpcDefinition(baseId);
		int[] configs = base == null ? null : base.getConfigs();
		if (configs != null)
		{
			for (int id : configs)
			{
				if (id > 0 && !npcIds.contains(id))
				{
					npcIds.add(id);
				}
			}
		}
		for (int offset = 1; offset <= 2; offset++)
		{
			if (!npcIds.contains(baseId + offset))
			{
				npcIds.add(baseId + offset);
			}
		}
	}

	/** A display name, or null for none: unnamed NPCs are called "null" in the game's data. */
	static String realName(String name)
	{
		if (name == null)
		{
			return null;
		}
		String plain = Text.removeTags(name).trim().toLowerCase(Locale.ROOT);
		return plain.isEmpty() || plain.equals("null") ? null : plain;
	}
}

package com.salvagehelper;

import java.util.Locale;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/**
 * Recognises the game's salvaging lines. The phrases are what crewmates and the chat box say in
 * game, as collected by AFK Shipwrecks (BSD-2); matching is on lower-cased fragments so small
 * wording differences between crewmates still match.
 */
final class CrewSpeech
{
	private static final String HOLD_FULL = "cargo hold is full";
	private static final String[] CREW_SALVAGE = {"hook some salvage", "put it in the cargo hold"};
	private static final String PLAYER_DEPOSIT = "you deposit some cargo into the cargo hold";
	/** An order to a crewmate, e.g. "Ex-Captain Siad, take control of the ... hook!" or "..., take a rest!". */
	private static final Pattern CREW_ORDER = Pattern.compile("^[^,]+, (?:take control of the .+|take a rest)!?$");
	/** The ghost crewmate only ever says variations of "Wooo wooo." */
	private static final Pattern GHOST = Pattern.compile("^(?:w+o+[ ,]*)+[.!]*$");

	private CrewSpeech()
	{
	}

	static boolean isHoldFull(String text)
	{
		return plain(text).contains(HOLD_FULL);
	}

	/** A crewmate saying they hooked a piece of salvage (the ghost's "wooo" counts too). */
	static boolean isCrewSalvage(String text)
	{
		String line = plain(text);
		if (line.contains(HOLD_FULL))
		{
			return false;
		}
		for (String fragment : CREW_SALVAGE)
		{
			if (line.contains(fragment))
			{
				return true;
			}
		}
		return GHOST.matcher(line.trim()).matches();
	}

	static boolean isPlayerDeposit(String text)
	{
		return plain(text).contains(PLAYER_DEPOSIT);
	}

	static boolean isCrewOrder(String text)
	{
		return CREW_ORDER.matcher(Text.removeTags(text).trim()).matches();
	}

	private static String plain(String text)
	{
		return text == null ? "" : Text.removeTags(text).toLowerCase(Locale.ROOT);
	}
}

package com.salvagehelper;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Renderable;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.util.Text;

/**
 * Decides which of the player's crewmates are idle (not on a salvaging hook) and should be hidden.
 *
 * <h3>How "on a hook" is detected</h3>
 * <ol>
 *   <li><b>Job assignment (primary).</b> The game's crew varbits say which job each crewmate is on
 *   (see {@link CrewRoster}); a crewmate assigned to a hook counts as on it, anyone else (idle, sails,
 *   repairs...) does not. This is exact and does not care where they are walking.</li>
 *   <li><b>Animation (fallback)</b> for a crewmate that cannot be matched to a crew slot: the
 *   {@link SalvageIds#HOOK_OPERATOR_ANIMATIONS} set.</li>
 *   <li><b>Proximity (optional, fallback only).</b> Within {@link #HOOK_PROXIMITY_TILES} tiles of a
 *   hook. Off by default: much of a deck is that close to a hook, so it kept walking crew visible.</li>
 * </ol>
 * A crewmate is only hidden once they have been off a hook for longer than the grace period, so
 * they do not flicker in and out.
 *
 * <h3>Scope</h3>
 * Hiding only applies while the player stands on a boat whose WorldEntity owner type says it is
 * theirs, and only to crewmate NPCs in that boat's world view. Other players, other NPCs, other
 * people's crews and the local player are never touched.
 */
@Slf4j
@Singleton
class CrewTracker
{
	/** Distance, in tiles, at which a crewmate counts as standing at a hook for the fallback. */
	private static final int HOOK_PROXIMITY_TILES = 2;

	private final Client client;
	private final SalvageHelperConfig config;
	private final BoatObjects boatObjects;
	private final CrewRoster crewRoster;

	/** Last game tick each crewmate was seen on a hook (or first seen, so new crew get a grace period). */
	private final Map<NPC, Integer> lastOnHookTick = new HashMap<>();
	/** Crewmates to skip when drawing. Read by the draw callback, written on game ticks (both client thread). */
	private final Set<NPC> hidden = new HashSet<>();
	/** Last crew report written to the log. */
	private String lastReport;

	@Inject
	CrewTracker(Client client, SalvageHelperConfig config, BoatObjects boatObjects, CrewRoster crewRoster)
	{
		this.client = client;
		this.config = config;
		this.boatObjects = boatObjects;
		this.crewRoster = crewRoster;
	}

	void npcDespawned(NPC npc)
	{
		lastOnHookTick.remove(npc);
		hidden.remove(npc);
	}

	/** Forgets all crew state and shows everyone again. */
	void reset()
	{
		lastOnHookTick.clear();
		hidden.clear();
		lastReport = null;
	}

	/** Recomputes the hidden set. Called once per game tick. */
	void update()
	{
		hidden.clear();
		if (!config.hideIdleCrewmates())
		{
			return;
		}

		// Crew live in the boat's own world view; only the player's own boat counts
		WorldView boat = boatObjects.ownBoatView();
		if (boat == null)
		{
			lastOnHookTick.clear();
			return;
		}

		int tick = client.getTickCount();
		int grace = config.graceTicks();
		Set<NPC> seen = new HashSet<>();
		List<CrewRoster.Member> members = crewRoster.members();
		TreeSet<String> report = new TreeSet<>();

		for (NPC npc : boat.npcs())
		{
			if (npc == null)
			{
				continue;
			}
			CrewRoster.Member member = CrewRoster.find(members, npc);
			if (member == null && !isCrewmate(npc))
			{
				report.add(describe(npc, null) + " not crew");
				continue;
			}
			seen.add(npc);

			// The game's own job assignment decides when the crewmate can be matched to a slot; the
			// animation (and optional proximity) guess is only for crew that cannot be matched
			boolean onHook = member != null ? member.onHook() : isOnHook(npc, boat);
			if (onHook)
			{
				lastOnHookTick.put(npc, tick);
			}
			else
			{
				int last = lastOnHookTick.computeIfAbsent(npc, n -> tick);
				if (tick - last > grace)
				{
					hidden.add(npc);
				}
			}
			report.add(describe(npc, member) + (onHook ? " on hook" : " idle") + (hidden.contains(npc) ? " HIDDEN" : ""));
		}

		lastOnHookTick.keySet().retainAll(seen);
		logOnChange(members, report);
	}

	private static String describe(NPC npc, CrewRoster.Member member)
	{
		NPCComposition transformed = npc.getTransformedComposition();
		return Text.removeTags(String.valueOf(npc.getName())) + " (npc " + npc.getId()
			+ (transformed != null && transformed.getId() != npc.getId() ? "/" + transformed.getId() : "")
			+ (member != null ? ", job " + member.position : ", no crew slot match") + ")";
	}

	/**
	 * Writes what the hider sees to the debug log whenever it changes, so a crewmate that is not
	 * hidden can be diagnosed from the debug log (client started with --debug).
	 */
	private void logOnChange(List<CrewRoster.Member> members, TreeSet<String> report)
	{
		StringBuilder slots = new StringBuilder();
		for (CrewRoster.Member member : members)
		{
			slots.append(slots.length() == 0 ? "" : ", ")
				.append(member.uniqueId).append(" job ").append(member.position).append(" npcs ").append(member.npcIds);
		}
		String summary = "crew slots [" + slots + "], boat NPCs " + (report.isEmpty() ? "[none]" : report);
		if (!summary.equals(lastReport))
		{
			lastReport = summary;
			log.debug("Crew hider: {}", summary);
		}
	}

	/** RenderCallback.addEntity body: false skips drawing the model and its overhead text/hitsplats. */
	boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		return !(renderable instanceof NPC) || !hidden.contains(renderable);
	}

	static boolean isCrewmate(NPC npc)
	{
		if (SalvageIds.CREWMATE_NPC_IDS.contains(npc.getId()))
		{
			return true;
		}
		// Crewmates may be multi-NPCs that transform with varbits; check the resolved ID as well.
		NPCComposition transformed = npc.getTransformedComposition();
		return transformed != null && SalvageIds.CREWMATE_NPC_IDS.contains(transformed.getId());
	}

	private boolean isOnHook(NPC npc, WorldView boat)
	{
		if (SalvageIds.HOOK_OPERATOR_ANIMATIONS.contains(npc.getAnimation()))
		{
			return true;
		}

		if (!config.hookProximityFallback())
		{
			return false;
		}

		LocalPoint npcPos = npc.getLocalLocation();
		if (npcPos == null)
		{
			return false;
		}

		int maxDistance = HOOK_PROXIMITY_TILES * Perspective.LOCAL_TILE_SIZE;
		for (GameObject hook : boatObjects.ownHooks())
		{
			LocalPoint hookPos = hook.getLocalLocation();
			if (hookPos != null && hookPos.distanceTo(npcPos) <= maxDistance)
			{
				return true;
			}
		}
		return false;
	}
}

package com.salvagehelper;

final class Durations
{
	private Durations()
	{
	}

	/** "4:05", or "1:02:30" past an hour. Negative becomes 0:00. */
	static String countdown(long millis)
	{
		long seconds = Math.max(0, millis / 1000);
		long hours = seconds / 3600;
		long minutes = seconds / 60 % 60;
		long secs = seconds % 60;
		return hours > 0
			? String.format("%d:%02d:%02d", hours, minutes, secs)
			: String.format("%d:%02d", minutes, secs);
	}

	/** "52 min", "1 h 05 min", or "<1 min". */
	static String approx(long millis)
	{
		long minutes = Math.max(0, millis / 60_000);
		if (minutes < 1)
		{
			return "<1 min";
		}
		return minutes >= 60 ? String.format("%d h %02d min", minutes / 60, minutes % 60) : minutes + " min";
	}
}

package com.salvagehelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.ColorUtil;

/**
 * Writes the slot count on your cargo hold ("39/160", "~39/160" while estimated), fading from green
 * through yellow at half full to red when full.
 */
class HoldCountOverlay extends Overlay
{
	private static final Color EMPTY = new Color(80, 220, 80);
	private static final Color HALF = new Color(255, 255, 0);
	private static final Color FULL = new Color(255, 0, 0);
	/** Draw the text a little above the hold's base. */
	private static final int Z_OFFSET = 60;

	private final SalvageHelperConfig config;
	private final BoatObjects boatObjects;
	private final CargoHoldTracker cargoHoldTracker;

	@Inject
	HoldCountOverlay(SalvageHelperConfig config, BoatObjects boatObjects, CargoHoldTracker cargoHoldTracker)
	{
		this.config = config;
		this.boatObjects = boatObjects;
		this.cargoHoldTracker = cargoHoldTracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.countOnHold())
		{
			return null;
		}
		GameObject hold = boatObjects.ownCargoHold();
		CargoHoldTracker.Contents contents = cargoHoldTracker.current();
		if (hold == null || contents == null)
		{
			return null;
		}

		String text = (contents.isEstimate() ? "~" : "") + contents.getUsed()
			+ (contents.getCapacity() > 0 ? "/" + contents.getCapacity() : "");
		Point at = hold.getCanvasTextLocation(graphics, text, Z_OFFSET);
		if (at != null)
		{
			OverlayUtil.renderTextLocation(graphics, at, text, color(contents));
		}
		return null;
	}

	private static Color color(CargoHoldTracker.Contents contents)
	{
		if (contents.getCapacity() <= 0)
		{
			return Color.WHITE;
		}
		double fill = Math.min(1, (double) contents.getUsed() / contents.getCapacity());
		return fill < 0.5
			? ColorUtil.colorLerp(EMPTY, HALF, fill * 2)
			: ColorUtil.colorLerp(HALF, FULL, (fill - 0.5) * 2);
	}
}

package com.salvagehelper;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/** Time until the cargo hold is full at the recent fill rate. */
class HoldEtaInfoBox extends InfoBox
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm");

	private final CargoHoldTracker cargoHoldTracker;

	HoldEtaInfoBox(BufferedImage image, Plugin plugin, CargoHoldTracker cargoHoldTracker)
	{
		super(image, plugin);
		this.cargoHoldTracker = cargoHoldTracker;
	}

	@Override
	public String getText()
	{
		long millis = cargoHoldTracker.millisToFull();
		if (millis < 0)
		{
			return "...";
		}
		long minutes = millis / 60_000;
		return minutes >= 60 ? (minutes / 60) + "h" + (minutes % 60) : minutes + "m";
	}

	@Override
	public Color getTextColor()
	{
		return cargoHoldTracker.millisToFull() == 0 ? Color.RED : Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		long millis = cargoHoldTracker.millisToFull();
		if (millis < 0)
		{
			return "Cargo hold full in: working out the rate</br>Needs a few minutes of salvage coming in";
		}
		if (millis == 0)
		{
			return "Cargo hold is full";
		}
		return "Cargo hold full in about " + Durations.approx(millis)
			+ "</br>Around " + LocalTime.now().plusSeconds(millis / 1000).format(CLOCK);
	}
}

