package com.salvagehelper;

import com.google.inject.Provides;
import java.util.Locale;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.InfoBoxMenuClicked;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Salvage Helper",
	description = "Sailing salvaging: cargo hold swap, count and alerts, wreck timers and double spots, crew reminders and more",
	tags = {"sailing", "salvage", "salvaging", "cargo", "hold", "crew", "crewmate", "hook", "wreck", "shipwreck",
		"timer", "afk", "swap", "hide", "notify", "banner"}
)
public class SalvageHelperPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SalvageHelperConfig config;

	@Inject
	private CargoHoldSwapper cargoHoldSwapper;

	@Inject
	private CrewTracker crewTracker;

	@Inject
	private BoatObjects boatObjects;

	@Inject
	private CargoHoldTracker cargoHoldTracker;

	@Inject
	private WreckTracker wreckTracker;

	@Inject
	private SalvageSession session;

	@Inject
	private HookMonitor hookMonitor;

	@Inject
	private SalvageAlerts alerts;

	@Inject
	private Reminders reminders;

	@Inject
	private Banner banner;

	@Inject
	private BannerOverlay bannerOverlay;

	@Inject
	private HoldCountOverlay holdCountOverlay;

	@Inject
	private HoldSalvageOverlay holdSalvageOverlay;

	@Inject
	private NextStepOverlay nextStepOverlay;

	@Inject
	private WreckOverlay wreckOverlay;

	@Inject
	private SalvageCounterOverlay counterOverlay;

	/** Crew salvage lines seen since the last game tick. */
	private int crewLinesThisTick;
	/** The game said the player deposited into the hold since the last tick. */
	private boolean depositMessage;
	/** Tick the player clicked a deposit option on the hold, or -1. */
	private int depositClickTick = -1;
	/** How long after the click the inventory may take to empty (the walk to the hold). */
	private static final int DEPOSIT_WINDOW_TICKS = 30;

	// Same mechanism as the core Entity Hider: returning false from addEntity skips that actor
	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean addEntity(Renderable renderable, boolean ui)
		{
			return crewTracker.shouldDraw(renderable, ui);
		}
	};

	@Provides
	SalvageHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SalvageHelperConfig.class);
	}

	@Override
	protected void startUp()
	{
		renderCallbackManager.register(renderCallback);
		overlayManager.add(wreckOverlay);
		overlayManager.add(holdCountOverlay);
		overlayManager.add(nextStepOverlay);
		overlayManager.add(holdSalvageOverlay);
		overlayManager.add(counterOverlay);
		overlayManager.add(bannerOverlay);
		alerts.startUp(this);
		clientThread.invokeLater(cargoHoldSwapper::reloadConfig);
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(renderCallback);
		overlayManager.remove(wreckOverlay);
		overlayManager.remove(holdCountOverlay);
		overlayManager.remove(nextStepOverlay);
		overlayManager.remove(holdSalvageOverlay);
		overlayManager.remove(counterOverlay);
		overlayManager.remove(bannerOverlay);
		alerts.shutDown();
		cargoHoldSwapper.reset();
		resetState();
		// Turning the plugin off ends the counter session too; a logout only pauses it
		session.reset();
	}

	private void resetState()
	{
		crewTracker.reset();
		boatObjects.reset();
		cargoHoldTracker.reset();
		wreckTracker.reset();
		session.loggedOut();
		hookMonitor.reset();
		reminders.reset();
		banner.reset();
		crewLinesThisTick = 0;
		depositMessage = false;
		depositClickTick = -1;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SalvageHelperConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("cargoLimit".equals(event.getKey()))
		{
			alerts.limitChanged();
		}

		clientThread.invokeLater(() ->
		{
			cargoHoldSwapper.reloadConfig();
			if (!config.hideIdleCrewmates())
			{
				crewTracker.reset();
			}
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		// Every world view is torn down on these, so drop stale references
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			resetState();
		}
		// The sea (top-level scene) is rebuilt on a region load and its wrecks spawn again. Boats keep
		// their own world views, so their hooks and holds are left alone.
		else if (state == GameState.LOADING)
		{
			wreckTracker.reset();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			cargoHoldSwapper.updateInventory(event.getItemContainer());
		}
		else
		{
			cargoHoldTracker.containerChanged(event.getContainerId(), event.getItemContainer());
		}
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		Actor actor = event.getActor();
		String text = event.getOverheadText();
		WorldView theirs = actor.getWorldView();
		if (text == null || text.isEmpty() || theirs == null)
		{
			return;
		}

		WorldView mine = boatObjects.ownBoatView();
		boolean onMyBoat = mine != null && theirs == mine;
		SalvageHelperConfig.CrewTextMode hide = config.hideCrewText();

		if (actor instanceof NPC)
		{
			if (theirs.isTopLevel())
			{
				// Crew always stand on a boat
				return;
			}
			if (onMyBoat)
			{
				readCrewLine(text);
			}
			if (hide == SalvageHelperConfig.CrewTextMode.ALL_BOATS
				|| (hide == SalvageHelperConfig.CrewTextMode.OWN_BOAT && onMyBoat))
			{
				actor.setOverheadText("");
			}
		}
		else if (actor instanceof Player && CrewSpeech.isCrewOrder(text))
		{
			boolean mineToHide = actor == client.getLocalPlayer() || onMyBoat;
			if (hide == SalvageHelperConfig.CrewTextMode.ALL_BOATS
				|| (hide == SalvageHelperConfig.CrewTextMode.OWN_BOAT && mineToHide))
			{
				actor.setOverheadText("");
			}
		}
	}

	private void readCrewLine(String text)
	{
		if (CrewSpeech.isHoldFull(text))
		{
			cargoHoldTracker.holdReportedFull();
		}
		else if (CrewSpeech.isCrewSalvage(text))
		{
			crewLinesThisTick++;
			cargoHoldTracker.crewSalvaged();
			reminders.crewLine();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (CrewSpeech.isPlayerDeposit(event.getMessage()))
		{
			depositMessage = true;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = Text.removeTags(event.getMenuOption()).toLowerCase(Locale.ROOT);
		String target = Text.removeTags(event.getMenuTarget()).toLowerCase(Locale.ROOT);
		if (target.contains("cargo hold") && option.contains("deposit") && !option.equals("deposit-held"))
		{
			depositClickTick = client.getTickCount();
		}
		else if (cancelsWalk(event.getMenuAction()))
		{
			// Walking or acting somewhere else means the player is no longer heading to the hold
			depositClickTick = -1;
		}
	}

	private static boolean cancelsWalk(MenuAction action)
	{
		switch (action)
		{
			case WALK:
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
			case NPC_FIRST_OPTION:
			case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION:
			case NPC_FOURTH_OPTION:
			case NPC_FIFTH_OPTION:
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (event.getActor() == client.getLocalPlayer() && event.getHitsplat().getAmount() > 0)
		{
			reminders.playerHit();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.SAILING)
		{
			session.sailingXpChanged(event.getXp());
		}
	}

	// Low priority so this runs after other plugins' menu swaps; otherwise a plugin that rewrites the
	// menu later in the same event puts the original left-click back
	@Subscribe(priority = -100)
	public void onPostMenuSort(PostMenuSort event)
	{
		cargoHoldSwapper.swap();
	}

	@Subscribe(priority = -100)
	public void onMenuOpened(MenuOpened event)
	{
		cargoHoldSwapper.menuOpened();
	}

	@Subscribe
	public void onInfoBoxMenuClicked(InfoBoxMenuClicked event)
	{
		if (alerts.isCargoInfoBox(event.getInfoBox())
			&& CargoInfoBox.SET_LIMIT_OPTION.equals(event.getEntry().getOption()))
		{
			alerts.promptForLimit();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Every container change and chat line of this tick has arrived by now
		Widget holdInterface = client.getWidget(InterfaceID.SailingBoatCargohold.UNIVERSE);
		boolean holdOpen = holdInterface != null && !holdInterface.isHidden();

		int usedBefore = session.getInventoryUsed();
		int salvageBefore = session.getInventorySalvage();
		int gained = session.tick(crewLinesThisTick, holdOpen);

		// A deposit on the closed hold never sends the hold's contents, so add what left the inventory.
		// The click starts it (the walk to the hold can take several ticks); the chat message, when the
		// game sends one, confirms it.
		int tick = client.getTickCount();
		boolean depositPending = depositMessage
			|| (depositClickTick >= 0 && tick - depositClickTick <= DEPOSIT_WINDOW_TICKS);
		int removed = usedBefore - session.getInventoryUsed();
		if (depositPending && !holdOpen && removed > 0)
		{
			cargoHoldTracker.playerDeposited(removed, salvageBefore - session.getInventorySalvage());
			depositClickTick = -1;
		}
		else if (depositClickTick >= 0 && tick - depositClickTick > DEPOSIT_WINDOW_TICKS)
		{
			depositClickTick = -1;
		}
		crewLinesThisTick = 0;
		depositMessage = false;

		if (gained > 0)
		{
			wreckTracker.salvageGained(boatObjects.ownHookWorldPoints());
		}
		wreckTracker.tick();

		boolean hookJustStopped = hookMonitor.tick(session.isOnBoat(), gained > 0);
		alerts.tick(session.isOnBoat(), hookJustStopped);
		reminders.tick();
		crewTracker.update();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject object = event.getGameObject();
		boatObjects.spawned(object);
		wreckTracker.spawned(object);
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject object = event.getGameObject();
		boatObjects.despawned(object);
		wreckTracker.despawned(object);
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		crewTracker.npcDespawned(event.getNpc());
	}
}

package com.salvagehelper;

import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.gameval.InventoryID;

/**
 * Per-tick salvaging state shared by the alerts and overlays: whether you're on your own boat, what
 * is in your inventory, what you are doing, and the salvage counter session.
 *
 * <h3>How salvage gains are counted</h3>
 * Two sources, so nothing is counted twice:
 * <ul>
 *   <li>your own hooking: a rise in inventory salvage while the cargo hold is closed (with it open,
 *   a rise is a withdrawal, not new salvage);</li>
 *   <li>your crew: each crewmate overhead line about hooking salvage, passed in by the plugin.</li>
 * </ul>
 */
@Singleton
class SalvageSession
{
	enum Activity
	{
		NONE,
		/** At a hook rolling for salvage. */
		HOOKING,
		/** At a hook with nothing to salvage (the wreck sank or none in reach). */
		AT_HOOK_IDLE,
		SORTING
	}

	private static final int INVENTORY_SIZE = 28;
	/** Salvaging animations loop with short gaps; keep the last activity this many ticks. */
	private static final int ACTIVITY_HOLD_TICKS = 3;

	private final Client client;
	private final SalvageHelperConfig config;
	private final BoatObjects boatObjects;

	@Getter
	private boolean onBoat;
	@Getter
	private int inventorySalvage;
	@Getter
	private int inventoryUsed;
	@Getter
	private boolean inventoryFull;
	@Getter
	private Activity activity = Activity.NONE;

	@Getter
	private int salvageGained;
	@Getter
	private int xpGained;
	@Getter
	private Instant start;
	private Instant lastGain;
	/** When the player logged out with a session running, or null. */
	private Instant pausedAt;

	private int previousSalvage = -1;
	private int lastSailingXp = -1;
	private int activitySeenTick;

	@Inject
	SalvageSession(Client client, SalvageHelperConfig config, BoatObjects boatObjects)
	{
		this.client = client;
		this.config = config;
		this.boatObjects = boatObjects;
	}

	/**
	 * Refreshes boat/inventory/activity state and the counter.
	 *
	 * @param crewSalvage crew salvage lines seen this tick
	 * @param holdOpen whether the cargo hold interface is open
	 * @return salvage gained this tick, yours and your crew's
	 */
	int tick(int crewSalvage, boolean holdOpen)
	{
		boolean wasOnBoat = onBoat;
		onBoat = boatObjects.isOnOwnBoat();
		scanInventory(client.getItemContainer(InventoryID.INV));
		updateActivity();

		int gained = 0;
		if (onBoat)
		{
			gained += crewSalvage;
			if (wasOnBoat && !holdOpen && previousSalvage >= 0)
			{
				gained += Math.max(0, inventorySalvage - previousSalvage);
			}
		}
		previousSalvage = inventorySalvage;

		Instant now = Instant.now();
		if (pausedAt != null)
		{
			// Back in game: move the session's clock past the time spent logged out
			Duration away = Duration.between(pausedAt, now);
			start = start == null ? null : start.plus(away);
			lastGain = lastGain == null ? null : lastGain.plus(away);
			pausedAt = null;
		}
		if (gained > 0)
		{
			if (start == null)
			{
				start = now;
			}
			salvageGained += gained;
			lastGain = now;
		}
		else if (lastGain != null
			&& Duration.between(lastGain, now).toMinutes() >= config.counterResetMinutes())
		{
			resetCounter();
		}

		return gained;
	}

	/** Called on every Sailing StatChanged. XP only counts while a counter session is running. */
	void sailingXpChanged(int xp)
	{
		if (lastSailingXp >= 0 && xp > lastSailingXp && start != null)
		{
			xpGained += xp - lastSailingXp;
		}
		lastSailingXp = xp;
	}

	boolean isCounting()
	{
		return start != null;
	}

	int salvagePerHour()
	{
		return perHour(salvageGained);
	}

	int xpPerHour()
	{
		return perHour(xpGained);
	}

	void resetCounter()
	{
		salvageGained = 0;
		xpGained = 0;
		start = null;
		lastGain = null;
	}

	/** Full reset, e.g. on logout or world hop. */
	void reset()
	{
		resetCounter();
		loggedOut();
		pausedAt = null;
	}

	/**
	 * Logout or world hop: forget what was in view, but keep the counter. Its clock is paused so the
	 * time spent logged out does not drag the per-hour rates down; {@link #tick} resumes it.
	 */
	void loggedOut()
	{
		if (start != null && pausedAt == null)
		{
			pausedAt = Instant.now();
		}
		onBoat = false;
		inventorySalvage = 0;
		inventoryUsed = 0;
		inventoryFull = false;
		activity = Activity.NONE;
		previousSalvage = -1;
		lastSailingXp = -1;
	}

	private void updateActivity()
	{
		Player local = client.getLocalPlayer();
		int animation = local == null ? -1 : local.getAnimation();
		Activity seen = Activity.NONE;
		if (SalvageIds.HOOK_WORKING_ANIMATIONS.contains(animation))
		{
			seen = Activity.HOOKING;
		}
		else if (SalvageIds.HOOK_IDLE_ANIMATIONS.contains(animation))
		{
			seen = Activity.AT_HOOK_IDLE;
		}
		else if (SalvageIds.SORTING_ANIMATIONS.contains(animation))
		{
			seen = Activity.SORTING;
		}

		int tick = client.getTickCount();
		if (seen != Activity.NONE)
		{
			activity = seen;
			activitySeenTick = tick;
		}
		else if (activity == Activity.AT_HOOK_IDLE && local != null && local.getPoseAnimation() == local.getIdlePoseAnimation())
		{
			// After a reset the bigger hooks play no animation at all, so stay "at the hook" until the
			// player starts moving
			activitySeenTick = tick;
		}
		else if (tick - activitySeenTick > ACTIVITY_HOLD_TICKS)
		{
			activity = Activity.NONE;
		}
	}

	private int perHour(int amount)
	{
		if (start == null)
		{
			return 0;
		}
		long seconds = Math.max(1, Duration.between(start, Instant.now()).getSeconds());
		return (int) (amount * 3600L / seconds);
	}

	private void scanInventory(ItemContainer inventory)
	{
		inventorySalvage = 0;
		inventoryUsed = 0;
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				if (item.getId() <= 0)
				{
					continue;
				}
				inventoryUsed++;
				if (SalvageIds.SALVAGE_ITEM_IDS.contains(item.getId()))
				{
					inventorySalvage += item.getQuantity();
				}
			}
		}
		inventoryFull = inventoryUsed >= INVENTORY_SIZE;
	}
}

package com.salvagehelper;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ObjectID;

/**
 * The eight shipwreck kinds. Object IDs are gameval constants; the Sailing level and lifetime are
 * game facts (OSRS wiki, as also tabulated by AFK Shipwrecks, BSD-2). A wreck that is up is the
 * plain object; once it sinks it is replaced by the _STUMP object at the same spot.
 */
@Getter
@RequiredArgsConstructor
enum ShipwreckType
{
	SMALL("Small", 15, 60, ObjectID.SAILING_SMALL_SHIPWRECK, ObjectID.SAILING_SMALL_SHIPWRECK_STUMP),
	FISHERMAN("Fisherman's", 26, 180, ObjectID.SAILING_FISHERMAN_SHIPWRECK, ObjectID.SAILING_FISHERMAN_SHIPWRECK_STUMP),
	BARRACUDA("Barracuda", 35, 180, ObjectID.SAILING_BARRACUDA_SHIPWRECK, ObjectID.SAILING_BARRACUDA_SHIPWRECK_STUMP),
	LARGE("Large", 53, 180, ObjectID.SAILING_LARGE_SHIPWRECK, ObjectID.SAILING_LARGE_SHIPWRECK_STUMP),
	PIRATE("Pirate", 64, 180, ObjectID.SAILING_PIRATE_SHIPWRECK, ObjectID.SAILING_PIRATE_SHIPWRECK_STUMP),
	MERCENARY("Mercenary", 73, 195, ObjectID.SAILING_MERCENARY_SHIPWRECK, ObjectID.SAILING_MERCENARY_SHIPWRECK_STUMP),
	FREMENNIK("Fremennik", 80, 223, ObjectID.SAILING_FREMENNIK_SHIPWRECK, ObjectID.SAILING_FREMENNIK_SHIPWRECK_STUMP),
	MERCHANT("Merchant", 87, 240, ObjectID.SAILING_MERCHANT_SHIPWRECK, ObjectID.SAILING_MERCHANT_SHIPWRECK_STUMP);

	private final String displayName;
	private final int sailingLevel;
	/** Longest a wreck stays up once first salvaged. */
	private final int lifetimeSeconds;
	private final int activeObjectId;
	private final int sunkObjectId;

	static ShipwreckType fromObjectId(int objectId)
	{
		for (ShipwreckType type : values())
		{
			if (type.activeObjectId == objectId || type.sunkObjectId == objectId)
			{
				return type;
			}
		}
		return null;
	}
}

package com.salvagehelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Draws on the sea around wrecks while you are on your own boat:
 * <ul>
 *   <li>an outline on each wreck that is up, and a timer on every wreck (see {@link WreckTracker});</li>
 *   <li>reach boxes: the square of sea where a hook can reach each wreck (8 tiles each way);</li>
 *   <li>double spot boxes: where two wrecks' reach squares overlap, so one hook reaches both. Once
 *   every hook on your boat is inside one, the box changes colour and says "Parked".</li>
 * </ul>
 */
class WreckOverlay extends Overlay
{
	private static final Color SUNK_COLOR = new Color(150, 150, 150);
	private static final Color TIMER_COLOR = new Color(80, 220, 255);
	private static final int FILL_ALPHA = 28;

	private final Client client;
	private final SalvageHelperConfig config;
	private final WreckTracker wreckTracker;
	private final BoatObjects boatObjects;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	WreckOverlay(Client client, SalvageHelperConfig config, WreckTracker wreckTracker, BoatObjects boatObjects,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.config = config;
		this.wreckTracker = wreckTracker;
		this.boatObjects = boatObjects;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<WorldPoint> hooks = boatObjects.ownHookWorldPoints();
		if (hooks.isEmpty())
		{
			// Not on your own boat, or it has no salvaging hook
			return null;
		}

		List<WreckTracker.Site> sites = new ArrayList<>(wreckTracker.sites());
		long now = System.currentTimeMillis();

		boolean parked = false;
		if (config.doubleSpotBoxes())
		{
			parked = drawDoubleSpots(graphics, sites, hooks);
		}

		if (config.reachBoxes() && !(parked && config.hideReachWhenParked()))
		{
			for (WreckTracker.Site site : sites)
			{
				Color color = site.isActive() ? config.reachColor() : SUNK_COLOR;
				drawBox(graphics, reachBox(site.getPoint()), color, null);
			}
		}

		for (WreckTracker.Site site : sites)
		{
			GameObject object = site.getObject();
			if (object == null)
			{
				continue;
			}
			if (config.outlineWrecks() && site.isActive())
			{
				modelOutlineRenderer.drawOutline(object, 2, config.reachColor(), 4);
			}
			if (config.wreckTimers())
			{
				String text = timerText(site, now);
				Point at = object.getCanvasTextLocation(graphics, text, 0);
				if (at != null)
				{
					OverlayUtil.renderTextLocation(graphics, at, text, site.isActive() ? TIMER_COLOR : SUNK_COLOR);
				}
			}
		}
		return null;
	}

	/** @return true if every hook is inside one of the boxes */
	private boolean drawDoubleSpots(Graphics2D graphics, List<WreckTracker.Site> sites, List<WorldPoint> hooks)
	{
		boolean anyParked = false;
		for (int i = 0; i < sites.size(); i++)
		{
			for (int j = i + 1; j < sites.size(); j++)
			{
				int[] box = overlap(reachBox(sites.get(i).getPoint()), reachBox(sites.get(j).getPoint()));
				if (box == null)
				{
					continue;
				}

				int inside = 0;
				for (WorldPoint hook : hooks)
				{
					if (contains(box, hook))
					{
						inside++;
					}
				}
				boolean parked = inside == hooks.size();
				anyParked |= parked;

				String label = null;
				if (config.labelDoubleSpots())
				{
					label = parked ? "Parked" : "Park here (" + inside + "/" + hooks.size() + ")";
				}
				drawBox(graphics, box, parked ? config.parkedColor() : config.doubleSpotColor(), label);
			}
		}
		return anyParked;
	}

	private String timerText(WreckTracker.Site site, long now)
	{
		if (site.isActive())
		{
			return site.getSinksBy() < 0 ? site.getType().getDisplayName() + " wreck"
				: "Sinks in ≤ " + Durations.countdown(site.getSinksBy() - now);
		}
		long next = wreckTracker.nextRiseBy();
		return next < 0 ? "Sunk" : "Sunk - next ≤ " + Durations.countdown(next - now);
	}

	/** {minX, minY, maxX, maxY, plane} of the sea a hook can reach the wreck from. */
	private static int[] reachBox(WorldPoint wreck)
	{
		int r = SalvageIds.HOOK_REACH_TILES;
		return new int[]{wreck.getX() - r, wreck.getY() - r, wreck.getX() + r, wreck.getY() + r, wreck.getPlane()};
	}

	private static int[] overlap(int[] a, int[] b)
	{
		if (a[4] != b[4])
		{
			return null;
		}
		int minX = Math.max(a[0], b[0]);
		int minY = Math.max(a[1], b[1]);
		int maxX = Math.min(a[2], b[2]);
		int maxY = Math.min(a[3], b[3]);
		return minX > maxX || minY > maxY ? null : new int[]{minX, minY, maxX, maxY, a[4]};
	}

	private static boolean contains(int[] box, WorldPoint point)
	{
		return point.getPlane() == box[4]
			&& point.getX() >= box[0] && point.getX() <= box[2]
			&& point.getY() >= box[1] && point.getY() <= box[3];
	}

	private void drawBox(Graphics2D graphics, int[] box, Color color, String label)
	{
		WorldView top = client.getTopLevelWorldView();
		if (top == null)
		{
			return;
		}
		int width = box[2] - box[0] + 1;
		int height = box[3] - box[1] + 1;
		LocalPoint southWest = LocalPoint.fromWorld(top, box[0], box[1]);
		if (southWest == null)
		{
			return;
		}
		// The polygon helper wants the middle of the area
		LocalPoint middle = southWest.plus((width - 1) * Perspective.LOCAL_TILE_SIZE / 2,
			(height - 1) * Perspective.LOCAL_TILE_SIZE / 2);
		Polygon poly = Perspective.getCanvasTileAreaPoly(client, middle, width, height, top.getPlane(), 0);
		if (poly == null)
		{
			return;
		}

		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(color);
		graphics.draw(poly);
		if (config.fillBoxes())
		{
			graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), FILL_ALPHA));
			graphics.fill(poly);
		}

		if (label != null)
		{
			Point at = Perspective.getCanvasTextLocation(client, graphics, middle, label, 0);
			if (at != null)
			{
				OverlayUtil.renderTextLocation(graphics, at, label, color);
			}
		}
	}
}

package com.salvagehelper;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;

/**
 * Shipwreck sites in view and how long each has left.
 *
 * <h3>Timers are upper limits</h3>
 * A wreck stays up for at most its {@link ShipwreckType#getLifetimeSeconds() lifetime} from the
 * moment anyone first salvages it, which the client cannot see. So a wreck's clock starts the first
 * time salvage comes in while it is in reach of one of your hooks: if someone else got there first
 * it really has less time, so the shown time is always "at most". A sunk wreck shows when the next
 * one can rise at the latest: in an area the wrecks share one pool, so one rises as another sinks,
 * meaning the earliest known sink among the wrecks still up bounds the next rise.
 */
@Singleton
class WreckTracker
{
	static final class Site
	{
		@Getter
		private final WorldPoint point;
		@Getter
		private final ShipwreckType type;
		@Getter
		private GameObject object;
		@Getter
		private boolean active;
		/** Latest time it can sink, or -1 if its clock has not started. */
		@Getter
		private long sinksBy = -1;

		Site(WorldPoint point, ShipwreckType type)
		{
			this.point = point;
			this.type = type;
		}

		boolean inReachOf(WorldPoint hook)
		{
			return hook != null && hook.getPlane() == point.getPlane()
				&& Math.abs(hook.getX() - point.getX()) <= SalvageIds.HOOK_REACH_TILES
				&& Math.abs(hook.getY() - point.getY()) <= SalvageIds.HOOK_REACH_TILES;
		}
	}

	private final Map<WorldPoint, Site> sites = new HashMap<>();

	void spawned(GameObject object)
	{
		ShipwreckType type = ShipwreckType.fromObjectId(object.getId());
		if (type == null || object.getWorldView() == null || !object.getWorldView().isTopLevel())
		{
			return;
		}

		WorldPoint point = object.getWorldLocation();
		Site site = sites.computeIfAbsent(point, p -> new Site(p, type));
		boolean active = object.getId() == type.getActiveObjectId();
		if (site.active != active)
		{
			// Rose or sank: either way the old clock no longer applies
			site.sinksBy = -1;
		}
		site.object = object;
		site.active = active;
	}

	void despawned(GameObject object)
	{
		Site site = sites.get(object.getWorldLocation());
		if (site != null && site.object == object)
		{
			site.object = null;
		}
	}

	/** Drops sites whose object went away and was not replaced (scene unloaded). Once per tick. */
	void tick()
	{
		Iterator<Site> it = sites.values().iterator();
		while (it.hasNext())
		{
			if (it.next().object == null)
			{
				it.remove();
			}
		}
	}

	/** Salvage came in this tick: start the clock of every wreck that is up and in reach of a hook. */
	void salvageGained(List<WorldPoint> hooks)
	{
		long now = System.currentTimeMillis();
		for (Site site : sites.values())
		{
			if (site.active && site.sinksBy < 0 && inReachOfAny(site, hooks))
			{
				site.sinksBy = now + site.type.getLifetimeSeconds() * 1000L;
			}
		}
	}

	Collection<Site> sites()
	{
		return sites.values();
	}

	/** Wrecks that are up and in reach of at least one of the given hooks. */
	List<Site> activeInReach(List<WorldPoint> hooks)
	{
		List<Site> result = new ArrayList<>();
		for (Site site : sites.values())
		{
			if (site.active && inReachOfAny(site, hooks))
			{
				result.add(site);
			}
		}
		return result;
	}

	/** Whether any wreck site (up or sunk) is within this many tiles of the point. */
	boolean anySiteNear(WorldPoint point, int tiles)
	{
		if (point == null)
		{
			return false;
		}
		for (Site site : sites.values())
		{
			if (site.point.distanceTo2D(point) <= tiles)
			{
				return true;
			}
		}
		return false;
	}

	/** Latest time the next wreck can rise: the earliest known sink among wrecks still up, or -1. */
	long nextRiseBy()
	{
		long earliest = -1;
		for (Site site : sites.values())
		{
			if (site.active && site.sinksBy >= 0 && (earliest < 0 || site.sinksBy < earliest))
			{
				earliest = site.sinksBy;
			}
		}
		return earliest;
	}

	void reset()
	{
		sites.clear();
	}

	private static boolean inReachOfAny(Site site, List<WorldPoint> hooks)
	{
		for (WorldPoint hook : hooks)
		{
			if (site.inReachOf(hook))
			{
				return true;
			}
		}
		return false;
	}
}

